//This ORM package provides separate read and write instance access, along with wrappers for common CRUD operations,
//and is not intended to replace GORM.
//
//It currently wraps standard create, query, update, delete, and pagination operations, and accepts an external logger
//that collects and outputs logs generated by these operations.
//
//Call R() or W() to select the read or write instance; see svc_test.go.
//
//For more advanced operations, use the syntax provided by GORM.

package orm

import (
	"context"
	"database/sql"

	"github.com/keepchen/go-sail/v3/lib/db"
	"github.com/keepchen/go-sail/v3/lib/logger"
	"go.uber.org/zap"
	"gorm.io/gorm"
)

type Svc interface {
	Model(value any) Svc
	Where(query any, args ...any) Svc
	Or(query any, args ...any) Svc
	Not(query any, args ...any) Svc
	Joins(query string, args ...any) Svc
	Select(query any, args ...any) Svc
	Omit(columns ...string) Svc
	Order(value any) Svc
	Group(name string) Svc
	Offset(offset int) Svc
	Limit(limit int) Svc
	Having(query any, args ...any) Svc
	Scopes(fns ...func(*gorm.DB) *gorm.DB) Svc
	Session(session *gorm.Session) Svc
	WithContext(ctx context.Context) Svc

	Count(count *int64)
	Create(value any) error
	Find(dest any, conditions ...any) error
	First(dest any, conditions ...any) error
	Updates(values any) error
	Save(values any) error
	Delete(value any, conditions ...any) error
	Transaction(fc func(tx *gorm.DB) error, opts ...*sql.TxOptions) (err error)

	// Unwrap returns the underlying GORM instance
	Unwrap() *gorm.DB

	// R uses the read instance
	R() Svc
	// W uses the write instance
	W() Svc
	// Paginate queries a page of records (multiple rows)
	//
	//Parameters:
	//
	//page page number, starting at 1
	//
	//pageSize items per page, default: 10
	//
	//Returns:
	//
	//Total count and error
	Paginate(dest any, page, pageSize int) (int64, error)
	// FindOrNil queries multiple records
	//
	//Ignore gorm.ErrRecordNotFound when records do not exist
	FindOrNil(dest any, conditions ...any) error
	// FirstOrNil queries a single record
	//
	//Ignore gorm.ErrRecordNotFound when records do not exist
	FirstOrNil(dest any, conditions ...any) error
}

type SvcImpl struct {
	dbr    *gorm.DB
	dbw    *gorm.DB
	tx     *gorm.DB
	logger *zap.Logger
}

var _ Svc = (*SvcImpl)(nil)

// New initializes
//
// Shorthand for NewSvcImpl
var New = NewSvcImpl

// NewSvcImpl initializes
var NewSvcImpl = func(dbr *gorm.DB, dbw *gorm.DB, logger *zap.Logger) Svc {
	return &SvcImpl{
		dbr:    dbr,
		dbw:    dbw,
		logger: logger,
	}
}

// NewSvcImplSilent initializes
//
// Use the default read/write instances and logger
var NewSvcImplSilent = func() Svc {
	return &SvcImpl{
		dbr:    db.GetInstance().R,
		dbw:    db.GetInstance().W,
		logger: logger.GetLogger(),
	}
}

func (a *SvcImpl) Model(value any) Svc {
	if a.tx == nil {
		a.tx = a.dbw
	}

	a.tx = a.tx.Model(value)

	return a
}

func (a *SvcImpl) Where(query any, args ...any) Svc {
	if a.tx == nil {
		a.tx = a.dbw
	}

	a.tx = a.tx.Where(query, args...)

	return a
}

